SELECT f.feature_id || ' → ' || f.requirement_id AS detail FROM project_feature_requirements f WHERE f.project_id = $1 AND NOT EXISTS (SELECT 1 FROM project_requirements r WHERE r.project_id = f.project_id AND r.id = f.requirement_id) AND NOT EXISTS (SELECT 1 FROM project_features pf JOIN project_named_id n ON n.project_id = pf.project_id AND n.entity_kind = pf.entity_kind AND n.entity_name = pf.entity_name WHERE pf.project_id = f.project_id AND pf.id = f.feature_id AND n.said_id = f.requirement_id AND n.caveated) ORDER BY 1
